import sys
import json
import os

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    fda_records = []
    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            data = json.load(f)
            fda_records = data.get("results", [])

    fda_by_entity = {}
    for rec in fda_records:
        entity = rec.get("recall_number")
        if entity:
            fda_by_entity.setdefault(entity, []).append(rec)

    schema = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "classification date": ("fda_enforcement_reports", "center_classification_date")
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "termination date": ("fda_enforcement_reports", "termination_date")
        }
    }

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            if rule_id not in schema or fact not in schema[rule_id]:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_name = schema[rule_id][fact]

            records = []
            if doc_name == "fda_enforcement_reports":
                records = fda_by_entity.get(entity, [])

            values = set()
            for rec in records:
                val = rec.get(field_name)
                if val is not None:
                    val = str(val).strip()
                    if val:
                        # Format date from YYYYMMDD to YYYY-MM-DD
                        if len(val) == 8 and val.isdigit():
                            val = f"{val[:4]}-{val[4:6]}-{val[6:]}"
                        values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
