import json
import sys
import os

def format_date(d):
    if not d:
        return "ABSENT"
    if isinstance(d, str) and len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return str(d)

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, "fda_enforcement_reports.json")

    data = {}
    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            fda_data = json.load(f)
            for row in fda_data.get("results", []):
                recall_number = row.get("recall_number")
                if not recall_number:
                    continue

                if recall_number not in data:
                    data[recall_number] = {
                        "recall_initiation_date": set(),
                        "center_classification_date": set(),
                        "termination_date": set()
                    }

                init_date = format_date(row.get("recall_initiation_date", ""))
                class_date = format_date(row.get("center_classification_date", ""))
                term_date = format_date(row.get("termination_date", ""))

                data[recall_number]["recall_initiation_date"].add(init_date)
                data[recall_number]["center_classification_date"].add(class_date)
                data[recall_number]["termination_date"].add(term_date)

    output = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::")
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_output = {}
        for fact in facts:
            if fact == "initiation date":
                field = "recall_initiation_date"
            elif fact == "classification date":
                field = "center_classification_date"
            elif fact == "termination date":
                field = "termination_date"
            else:
                continue

            if entity not in data:
                pair_output[fact] = "ABSENT"
            else:
                vals = data[entity][field]
                if len(vals) == 0:
                    pair_output[fact] = "ABSENT"
                elif len(vals) > 1:
                    pair_output[fact] = "CONFLICT"
                else:
                    val = list(vals)[0]
                    if val == "ABSENT":
                        pair_output[fact] = "ABSENT"
                    else:
                        pair_output[fact] = [val, "fda_enforcement_reports"]

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
